/** @file asteroid_field_sl.cpp Portable original ASTR fields with sparse issuance and contained renewal state.
 * @see docs/zz-reach2/upgrades/2026-10/r2sff1-space-fixes-features-1.md Groups22/26; unchanged row widths with source-era no-target admission.
 * @see docs/zz-reach2/upgrades/2026-10/m2o28-1-merge-oct28.md Group 17; era-aware writing with a lossless round-trip proof for older layouts.
 * No decoded record is installed, advanced, retired or regenerated by this codec.
 */
#include "../stdafx.h"
#include "asteroid_field_sl.h"
#include "../safeguards.h"

/** Portable byte accumulator for explicit native ASTR scalar fields; owns no live field. */
class AsteroidFieldWriter {
public:
	std::vector<uint8_t> bytes; ///< Sole transport buffer, transferred to the native RIFF writer after validation.
	/** @param value Unsigned saved representation. @param width Fixed admitted field width in bytes. Append the original network-order scalar. */
	void Unsigned(uint64_t value, uint8_t width)
	{
		// Explicit bytes preserve the original ASTR contract on every host;
		// writing struct/optional/Randomizer memory could alter later decisions.
		for (int shift = (width - 1) * 8; shift >= 0; shift -= 8) this->bytes.push_back(static_cast<uint8_t>(value >> shift));
	}
	/** @param point Signed Q16 native point; serialized as two explicit U32 representations. */
	void Point(SpacePoint point) { this->Unsigned(static_cast<uint32_t>(point.x), 4); this->Unsigned(static_cast<uint32_t>(point.y), 4); }
};

/** Bounded original payload view; a failed read cannot overrun or allocate an owner. */
class AsteroidFieldReader {
	std::span<const uint8_t> bytes;
	size_t offset = 0;
	bool valid = true;
public:
	/** @param bytes Complete already extent-bounded candidate payload. */
	explicit AsteroidFieldReader(std::span<const uint8_t> bytes) : bytes(bytes) {}
	/** @param width Exact admitted byte width, at most eight. @return Scalar, marking refusal instead of overrunning a truncated original row. */
	uint64_t Unsigned(uint8_t width)
	{
		// Any malformed scalar invalidates this complete payload; a zero fallback
		// cannot later pass Complete and become a fabricated default field.
		if (!this->valid || width > 8 || width > this->bytes.size() - this->offset) { this->valid = false; return 0; }
		uint64_t value = 0;
		for (uint8_t index = 0; index < width; ++index) value = (value << 8) | this->bytes[this->offset++];
		return value;
	}
	/** @return Original signed native Q16 point; no map conversion or clipping occurs here. */
	SpacePoint Point() { return {static_cast<int32_t>(this->Unsigned(4)), static_cast<int32_t>(this->Unsigned(4))}; }
	/** @return Whether exact original bytes were consumed with no truncation or hidden trailing payload. */
	bool Complete() const { return this->valid && this->offset == this->bytes.size(); }
};

/** @param era Genuine original source layout. @return Original fixed header plus its explicitly versioned trailers. */
static size_t AsteroidFieldFixedBytes(AsteroidFieldWireEra era)
{
	return 51 + (era >= AsteroidFieldWireEra::StarterInputs ? 26 : 0) + (era >= AsteroidFieldWireEra::Lifecycle ? ASTEROID_LIFECYCLE_WIRE_BYTES : 0);
}

/** @copydoc GetAsteroidFieldWireMaximum */
size_t GetAsteroidFieldWireMaximum(AsteroidFieldWireEra era)
{
	if (era >= AsteroidFieldWireEra::End) return 0;
	return AsteroidFieldFixedBytes(era) + (era >= AsteroidFieldWireEra::NativeMining ? 40 : 36) * size_t{MAX_ORBITAL_BODIES} + 34 * size_t{MAX_SPACE_SURVEY_PREVIEWS};
}

/** Accept bytes written in a layout older than the current one only if they describe the field exactly.
 * StarterInputs has no lifecycle trailer and dense IDs only; Lifecycle has no ownerless survey. The proof
 * decodes the bytes with that same layout and re-encodes both fields in the current layout: equal bytes mean
 * equal ASTR content (ID-ordered bodies, surveys, starter inputs and lifecycle state). Survey knowledge
 * belongs to SPKN and the body lookup is derived, so neither takes part.
 * @param field The field that was encoded.
 * @param bytes Its encoding in the older layout.
 * @param era That older layout.
 * @return The bytes, or refusal when the layout cannot hold this field.
 */
static std::optional<std::vector<uint8_t>> ProveOlderAsteroidLayout(const AsteroidField &field, std::vector<uint8_t> bytes, AsteroidFieldWireEra era)
{
	const auto decoded = DecodeAsteroidField(bytes, era);
	if (!decoded) return std::nullopt;
	const auto original = EncodeAsteroidField(field, AsteroidFieldWireEra::SurveyDeparture);
	const auto reread = EncodeAsteroidField(*decoded, AsteroidFieldWireEra::SurveyDeparture);
	if (!original || !reread || *original != *reread) return std::nullopt;
	return bytes;
}

/** @copydoc EncodeAsteroidField */
std::optional<std::vector<uint8_t>> EncodeAsteroidField(const AsteroidField &field, AsteroidFieldWireEra era)
{
	// Current files explicitly own issuance, lifecycle and initialized renewal.
	// Only the decoder may upgrade genuinely absent old schema fields. No writer
	// emits a layout before StarterInputs, and an unknown era writes nothing.
	if (era < AsteroidFieldWireEra::StarterInputs || era >= AsteroidFieldWireEra::End) return std::nullopt;
	if (!ValidateAsteroidField(field) || (field.generation_version != 0 && field.lifecycle_version != ASTEROID_LIFECYCLE_VERSION)) return std::nullopt;
	AsteroidFieldWriter writer;
	writer.bytes.reserve(AsteroidFieldFixedBytes(era) + 40 * field.bodies.size() + 34 * field.surveys.size());
	writer.Unsigned(field.generation_version, 2); writer.Unsigned(field.width, 4); writer.Unsigned(field.height, 4);
	writer.Unsigned(field.seed, 8); writer.Unsigned(field.elapsed_ticks, 8); writer.Unsigned(to_underlying(field.density), 1);
	writer.Unsigned(field.bodies.size(), 4); writer.Unsigned(field.surveys.size(), 4); writer.Point(field.band.min); writer.Point(field.band.max);
	// Wire order depends only on original IDs, never compact-vector erasure
	// history. The disposable lookup and spatial buckets are never serialized.
	for (const auto *record : GetAsteroidBodiesInIDOrder(field)) {
		const auto &body = *record;
		writer.Unsigned(body.id.base(), 4); writer.Unsigned(to_underlying(body.resource_class), 1); writer.Unsigned(to_underlying(body.size), 1);
		writer.Point(body.motion.position); writer.Unsigned(static_cast<uint32_t>(body.motion.velocity_x), 4); writer.Unsigned(static_cast<uint32_t>(body.motion.velocity_y), 4);
		writer.Unsigned(body.motion.remainder_x, 1); writer.Unsigned(body.motion.remainder_y, 1);
		writer.Unsigned(body.initial_reserve, 4); writer.Unsigned(body.remaining_reserve, 4); writer.Unsigned(body.survey_slot.base(), 4); writer.Unsigned(body.mining_slot.base(), 4);
	}
	// Original ownerless preview phases retain their same bounded physical
	// records; this transport grants neither a native hull nor scan knowledge.
	for (const auto &survey : field.surveys) {
		writer.Unsigned(survey.id.base(), 4); writer.Unsigned(survey.model, 2); writer.Point(survey.position); writer.Point(survey.home);
		writer.Unsigned(survey.target.base(), 4); writer.Unsigned(to_underlying(survey.phase), 1); writer.Unsigned(survey.remaining_ticks, 2);
		writer.Unsigned(survey.travel_remainder, 1); writer.Unsigned(survey.completed_surveys, 4);
	}
	const auto &input = field.starter_input;
	writer.Unsigned(to_underlying(input.kind), 1); writer.Unsigned(input.site_x, 4); writer.Unsigned(input.site_y, 4);
	writer.Unsigned(input.rotation, 1); writer.Point(input.preference); writer.Unsigned(input.initial_approach_distance_squared, 8);
	if (era < AsteroidFieldWireEra::Lifecycle) return ProveOlderAsteroidLayout(field, std::move(writer.bytes), era);
	const auto &renewal = field.renewal;
	writer.Unsigned(field.lifecycle_version, 2); writer.Unsigned(field.next_body_id, 4); writer.Unsigned(renewal.initialized, 1);
	// Dedicated terminal-size counters and credit never represent cargo units.
	// Persist both complete independent streams so a failed attempt or a save
	// before the next interval cannot silently change its next proposal.
	for (const auto exits : renewal.exited_by_size) writer.Unsigned(exits, 8);
	writer.Unsigned(renewal.credits, 8); writer.Unsigned(renewal.last_exit.has_value(), 1);
	writer.Unsigned(renewal.last_exit ? to_underlying(renewal.last_exit->size) : 0, 1);
	writer.Unsigned(renewal.last_exit ? to_underlying(renewal.last_exit->resource_class) : 0, 1);
	writer.Unsigned(renewal.ticks_remaining, 4);
	for (const auto word : renewal.timer_rng.state) writer.Unsigned(word, 4);
	for (const auto word : renewal.candidate_rng.state) writer.Unsigned(word, 4);
	if (era < AsteroidFieldWireEra::SurveyDeparture) return ProveOlderAsteroidLayout(field, std::move(writer.bytes), era);
	return std::move(writer.bytes);
}

/** @copydoc DecodeAsteroidField */
std::optional<AsteroidField> DecodeAsteroidField(std::span<const uint8_t> bytes, AsteroidFieldWireEra era)
{
	// Bound the complete payload and exact layout before any body/survey vector
	// allocation. The caller selects the genuine era; bytes cannot opt into one.
	if (era >= AsteroidFieldWireEra::End || bytes.size() < AsteroidFieldFixedBytes(era) || bytes.size() > GetAsteroidFieldWireMaximum(era)) return std::nullopt;
	AsteroidFieldReader reader(bytes); AsteroidField field;
	field.generation_version = reader.Unsigned(2); field.width = reader.Unsigned(4); field.height = reader.Unsigned(4);
	field.seed = reader.Unsigned(8); field.elapsed_ticks = reader.Unsigned(8); field.density = static_cast<AsteroidDensity>(reader.Unsigned(1));
	const auto bodies = reader.Unsigned(4), surveys = reader.Unsigned(4);
	const uint64_t body_bytes = era >= AsteroidFieldWireEra::NativeMining ? 40 : 36;
	// Counts are read as bounded U32 values into U64 arithmetic. Their products
	// cannot wrap and must explain every byte before allocating native records.
	if (bodies > MAX_ORBITAL_BODIES || surveys > MAX_SPACE_SURVEY_PREVIEWS || bytes.size() != AsteroidFieldFixedBytes(era) + bodies * body_bytes + surveys * 34) return std::nullopt;
	field.band.min = reader.Point(); field.band.max = reader.Point();
	field.bodies.resize(static_cast<size_t>(bodies)); field.surveys.resize(static_cast<size_t>(surveys));
	uint32_t previous = 0; bool first = true;
	// Preserve canonical wire order and original source-era identity bounds.
	// Sorting corrupt input here would hide duplicates/descending row history.
	for (auto &body : field.bodies) {
		body.id = OrbitalBodyID{static_cast<uint32_t>(reader.Unsigned(4))}; body.resource_class = static_cast<AsteroidClass>(reader.Unsigned(1)); body.size = static_cast<AsteroidSize>(reader.Unsigned(1));
		body.motion.position = reader.Point(); body.motion.velocity_x = static_cast<int32_t>(reader.Unsigned(4)); body.motion.velocity_y = static_cast<int32_t>(reader.Unsigned(4));
		body.motion.remainder_x = reader.Unsigned(1); body.motion.remainder_y = reader.Unsigned(1);
		body.initial_reserve = reader.Unsigned(4); body.remaining_reserve = reader.Unsigned(4); body.survey_slot = SpaceSurveyID{static_cast<uint32_t>(reader.Unsigned(4))};
		if (era >= AsteroidFieldWireEra::NativeMining) body.mining_slot = VehicleID{static_cast<uint32_t>(reader.Unsigned(4))};
		if (!first && body.id.base() <= previous) return std::nullopt;
		// A genuine old field stored dense IDs and retained every body inside its
		// generation band; it cannot smuggle lifecycle geometry/history backward.
		if (era < AsteroidFieldWireEra::Lifecycle && (body.id.base() != static_cast<uint32_t>(&body - field.bodies.data()) || !field.band.Contains(body.motion.position))) return std::nullopt;
		previous = body.id.base(); first = false;
	}
	// Original survey records are decoded unchanged, then their complete phase,
	// geometry and both lease directions validate together with the field.
	for (auto &survey : field.surveys) {
		survey.id = SpaceSurveyID{static_cast<uint32_t>(reader.Unsigned(4))}; survey.model = reader.Unsigned(2); survey.position = reader.Point(); survey.home = reader.Point();
		survey.target = OrbitalBodyID{static_cast<uint32_t>(reader.Unsigned(4))}; survey.phase = static_cast<SpaceSurveyPhase>(reader.Unsigned(1)); survey.remaining_ticks = reader.Unsigned(2);
		survey.travel_remainder = reader.Unsigned(1); survey.completed_surveys = reader.Unsigned(4);
		// Before445 an original preview always named a live body, including its
		// Return/Waiting phases. Unchanged bytes cannot forge the new no-target
		// capability into a genuine older source. Valid old rows migrate intact.
		if (era < AsteroidFieldWireEra::SurveyDeparture && survey.target == INVALID_ORBITAL_BODY) return std::nullopt;
	}
	if (era >= AsteroidFieldWireEra::StarterInputs) {
		auto &input = field.starter_input;
		input.kind = static_cast<AsteroidStarterKind>(reader.Unsigned(1)); input.site_x = reader.Unsigned(4); input.site_y = reader.Unsigned(4);
		input.rotation = reader.Unsigned(1); input.preference = reader.Point(); input.initial_approach_distance_squared = reader.Unsigned(8);
	}
	if (era >= AsteroidFieldWireEra::Lifecycle) {
		field.lifecycle_version = reader.Unsigned(2); field.next_body_id = reader.Unsigned(4);
		auto &renewal = field.renewal; const auto initialized = reader.Unsigned(1);
		renewal.initialized = initialized != 0;
		for (auto &exits : renewal.exited_by_size) exits = reader.Unsigned(8);
		renewal.credits = reader.Unsigned(8); const auto last = reader.Unsigned(1);
		const auto size = reader.Unsigned(1), mineral = reader.Unsigned(1);
		// Optional absence has one canonical representation; arbitrary presence
		// flags or hidden last-exit bytes cannot invent credit/history after load.
		if (initialized > 1 || last > 1 || (last == 0 && (size != 0 || mineral != 0))) return std::nullopt;
		if (last != 0) renewal.last_exit = AsteroidExitMetadata{static_cast<AsteroidSize>(size), static_cast<AsteroidClass>(mineral)};
		renewal.ticks_remaining = reader.Unsigned(4);
		for (auto &word : renewal.timer_rng.state) word = reader.Unsigned(4);
		for (auto &word : renewal.candidate_rng.state) word = reader.Unsigned(4);
		// Current active fields cannot use the old absent-cursor/ledger fallback;
		// inactive current fields retain the exact canonical empty owner instead.
		if (field.generation_version != 0 && (field.lifecycle_version != ASTEROID_LIFECYCLE_VERSION || field.next_body_id == 0 || !renewal.initialized)) return std::nullopt;
	} else if (field.generation_version != 0) {
		// Upgrade only genuinely missing schema fields from the original saved
		// seed. Never regenerate bodies, starter history, velocities or reserves,
		// and never infer any historical exit from depletion or elapsed time.
		field.lifecycle_version = ASTEROID_LIFECYCLE_VERSION; field.next_body_id = static_cast<uint32_t>(bodies);
		field.renewal = MakeAsteroidRenewalState(field.seed);
	}
	if (!reader.Complete() || !ValidateAsteroidField(field) || !RebuildAsteroidBodyLookup(field)) return std::nullopt;
	return field;
}
